        # try to parse the arguments for this subparser
        try:
            # parse the arguments
            namespace = parser.parse_args(unparsed_arguments)
            # if the namespace is not null, store it under the subparser name
            if namespace:
                argument_namespaces[name] = namespace
        except:
            # if the parser fails to parse the arguments, silently ignore it
            pass

    # filter out any arguments that have already been claimed by subparsers
    for name, parser in subparsers.items():
        num_required = len(parser.positionals) + len(parser.optionals)
        if argument_namespaces[name]._actions.keys() == range(1, num_required+1):
            # if all required arguments are present, add any remaining arguments to the remaining list
            remaining_arguments += argument_namespaces[name]._actions[-1].startswith("--")
