def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time,
    return a corresponding datetime.timedelta instance or None
    if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency.lower() == "always":
        return None

    parts = frequency.lower().split(" ")
    number = int(parts[0])
    unit = parts[1]

    if unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit == "months":
        return datetime.timedelta(weeks=number*4)
    elif unit == "years":
        return datetime.timedelta(weeks=number*52)
    else:
        raise ValueError(f"Invalid frequency: {frequency}")
