    """Resolve arguments' values from spec and other sources. """
    spec = deepcopy(self.spec)
    for k, v in spec.items():
        if type(v) is str and v.startswith("_"):
            # resolve from other parameters in spec
            subparams = v.lstrip("_").split(".")
            for subparam in subparams:
                if subparam in spec:
                    spec[k] = spec[subparam]
                else:
                    raise ValueError(f"Invalid parameter spec: {k} depends on {v} but {v} is not defined")
        elif type(v) is dict:
            # resolving the default values for the parameters in the dict
            for key, val in v.items():
                if type(val) is str and val.startswith("_"):
                    subparams = val.lstrip("_").split(".")
                    for subparam in subparams:
